[{"id":"8fa8914","elType":"container","settings":[],"elements":[{"id":"e6c6e73","elType":"widget","settings":{"html":"<!--
  AM.TECH — премиальный макет страницы
  «Комплексные решения для промышленности»

  Формат: самостоятельный модуль для Elementor → виджет «HTML».
  Код рассчитан на замену контентной части страницы между шапкой и подвалом.
  Внешние библиотеки не используются.
-->

<section class="amsol" id="amtech-industrial-solutions">
  <style>
    .amsol {
      --amsol-orange: #ff7300;
      --amsol-orange-deep: #e65d00;
      --amsol-orange-soft: #fff1e5;
      --amsol-ink: #17191d;
      --amsol-ink-2: #24272d;
      --amsol-muted: #686d76;
      --amsol-line: #e5e7ea;
      --amsol-bg: #f5f5f3;
      --amsol-white: #fff;
      --amsol-radius-xl: 34px;
      --amsol-radius-lg: 24px;
      --amsol-radius-md: 17px;
      --amsol-shadow: 0 24px 70px rgba(21, 23, 28, 0.1);
      --amsol-header-clearance: 96px;
      position: relative;
      z-index: 0;
      color: var(--amsol-ink);
      background: var(--amsol-white);
      font-family: "Manrope", "Inter", "Segoe UI", Arial, sans-serif;
      font-size: 16px;
      line-height: 1.55;
      overflow: hidden;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    .amsol *,
    .amsol *::before,
    .amsol *::after {
      box-sizing: border-box;
      min-width: 0;
    }

    .amsol h1,
    .amsol h2,
    .amsol h3 {
      max-width: 100%;
      overflow-wrap: anywhere;
      word-break: normal;
      hyphens: auto;
    }

    .amsol img,
    .amsol svg {
      display: block;
      max-width: 100%;
    }

    .amsol a {
      color: inherit;
      text-decoration: none;
    }

    .amsol button {
      border: 0;
      font: inherit;
    }

    .amsol__container {
      width: min(1240px, calc(100% - 48px));
      margin: 0 auto;
    }

    .amsol__section {
      padding: 112px 0;
    }

    .amsol__section--soft {
      background: var(--amsol-bg);
    }

    .amsol__section--dark {
      color: var(--amsol-white);
      background:
        radial-gradient(circle at 88% 14%, rgba(255, 115, 0, 0.16), transparent 30%),
        #111317;
    }

    .amsol__eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin: 0 0 18px;
      color: var(--amsol-orange);
      font-size: 12px;
      font-weight: 800;
      letter-spacing: 0.13em;
      line-height: 1.25;
      text-transform: uppercase;
    }

    .amsol__eyebrow::before {
      width: 26px;
      height: 2px;
      background: currentColor;
      content: "";
    }

    .amsol__section-head {
      display: grid;
      grid-template-columns: minmax(0, 1.08fr) minmax(280px, 0.64fr);
      gap: 64px;
      align-items: end;
      margin-bottom: 50px;
    }

    .amsol__section-head h2 {
      max-width: 790px;
      margin: 0;
      color: inherit;
      font-size: clamp(36px, 4vw, 62px);
      font-weight: 650;
      letter-spacing: -0.045em;
      line-height: 1.03;
    }

    .amsol__section-head p {
      margin: 0;
      color: var(--amsol-muted);
      font-size: 17px;
      line-height: 1.7;
    }

    .amsol__section--dark .amsol__section-head p {
      color: #b1b5bd;
    }

    .amsol__button {
      position: relative;
      z-index: 1;
      display: inline-flex;
      min-height: 54px;
      align-items: center;
      justify-content: center;
      gap: 11px;
      padding: 14px 22px;
      border: 1px solid transparent;
      border-radius: 999px;
      cursor: pointer;
      font-size: 14px;
      font-weight: 780;
      line-height: 1;
      transition:
        transform 0.25s ease,
        background-color 0.25s ease,
        border-color 0.25s ease,
        color 0.25s ease,
        box-shadow 0.25s ease;
    }

    .amsol__button:hover {
      transform: translateY(-2px);
    }

    .amsol__button:focus-visible,
    .amsol__text-link:focus-visible,
    .amsol__modal-close:focus-visible,
    .amsol details summary:focus-visible {
      outline: 3px solid rgba(255, 115, 0, 0.36);
      outline-offset: 4px;
    }

    .amsol__button--primary {
      color: #fff;
      background: var(--amsol-orange);
      box-shadow: 0 14px 32px rgba(255, 115, 0, 0.28);
    }

    .amsol__button--primary:hover {
      background: var(--amsol-orange-deep);
      box-shadow: 0 18px 38px rgba(255, 115, 0, 0.34);
    }

    .amsol__button--ghost {
      border-color: rgba(255, 255, 255, 0.25);
      color: #fff;
      background: rgba(255, 255, 255, 0.06);
      backdrop-filter: blur(12px);
    }

    .amsol__button--ghost:hover {
      border-color: rgba(255, 255, 255, 0.46);
      background: rgba(255, 255, 255, 0.11);
    }

    .amsol__button--light {
      border-color: var(--amsol-line);
      color: var(--amsol-ink);
      background: #fff;
    }

    .amsol__button--light:hover {
      border-color: #cfd2d7;
      box-shadow: 0 12px 30px rgba(20, 22, 27, 0.08);
    }

    .amsol__button svg,
    .amsol__text-link svg {
      width: 18px;
      height: 18px;
      flex: 0 0 auto;
      fill: none;
      stroke: currentColor;
      stroke-linecap: round;
      stroke-linejoin: round;
      stroke-width: 1.8;
      transition: transform 0.25s ease;
    }

    .amsol__button:hover svg,
    .amsol__text-link:hover svg {
      transform: translateX(4px);
    }

    .amsol__text-link {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      padding: 0;
      border: 0;
      color: var(--amsol-orange);
      background: transparent;
      cursor: pointer;
      font-size: 14px;
      font-weight: 800;
    }

    /* Hero */
    .amsol__hero {
      position: relative;
      z-index: 0;
      min-height: 760px;
      color: #fff;
      background:
        radial-gradient(circle at 80% 18%, rgba(255, 115, 0, 0.2), transparent 28%),
        radial-gradient(circle at 14% 100%, rgba(255, 255, 255, 0.06), transparent 32%),
        #111317;
      isolation: isolate;
    }

    .amsol__hero::before {
      position: absolute;
      z-index: -1;
      inset: 0;
      opacity: 0.17;
      background-image:
        linear-gradient(rgba(255,255,255,.1) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,.1) 1px, transparent 1px);
      background-size: 68px 68px;
      mask-image: linear-gradient(to right, #000, transparent 78%);
      content: "";
      pointer-events: none;
    }

    .amsol__hero-grid {
      display: grid;
      min-height: 760px;
      grid-template-columns: minmax(0, 0.92fr) minmax(440px, 1.08fr);
      gap: 64px;
      align-items: center;
      padding: calc(76px + var(--amsol-header-clearance)) 0 70px;
    }

    .amsol__hero-copy {
      position: relative;
      z-index: 2;
      max-width: 660px;
    }

    .amsol__hero-kicker {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      margin-bottom: 26px;
      padding: 9px 13px;
      border: 1px solid rgba(255, 255, 255, 0.16);
      border-radius: 999px;
      color: #d5d7dc;
      background: rgba(255, 255, 255, 0.05);
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      backdrop-filter: blur(10px);
    }

    .amsol__hero-kicker::before {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--amsol-orange);
      box-shadow: 0 0 0 5px rgba(255, 115, 0, 0.14);
      content: "";
    }

    .amsol__hero h1 {
      margin: 0;
      color: #fff;
      font-size: clamp(48px, 5.6vw, 82px);
      font-weight: 640;
      letter-spacing: -0.055em;
      line-height: 0.98;
    }

    .amsol__hero h1 span {
      color: var(--amsol-orange);
    }

    .amsol__hero-lead {
      max-width: 610px;
      margin: 28px 0 0;
      color: #b9bdc5;
      font-size: clamp(17px, 1.5vw, 20px);
      line-height: 1.65;
    }

    .amsol__hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 34px;
    }

    .amsol__hero-facts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1px;
      margin-top: 48px;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.13);
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.13);
    }

    .amsol__hero-fact {
      min-height: 98px;
      padding: 19px 17px;
      background: rgba(17, 19, 23, 0.89);
    }

    .amsol__hero-fact strong {
      display: block;
      margin-bottom: 4px;
      color: #fff;
      font-size: 22px;
      font-weight: 750;
      letter-spacing: -0.03em;
    }

    .amsol__hero-fact span {
      display: block;
      color: #9da2ac;
      font-size: 12px;
      line-height: 1.45;
    }

    .amsol__hero-visual {
      position: relative;
      min-height: 590px;
    }

    .amsol__visual-card {
      position: absolute;
      inset: 56px 0 38px;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.16);
      border-radius: 32px;
      background: #1d2026;
      box-shadow: 0 40px 90px rgba(0, 0, 0, 0.34);
    }

    .amsol__visual-card::after {
      position: absolute;
      inset: 0;
      background:
        linear-gradient(to top, rgba(13, 15, 18, 0.92), transparent 55%),
        linear-gradient(90deg, rgba(13, 15, 18, 0.35), transparent 45%);
      content: "";
    }

    .amsol__visual-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .amsol__visual-label {
      position: absolute;
      z-index: 2;
      right: 24px;
      bottom: 24px;
      left: 24px;
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 20px;
    }

    .amsol__visual-label span {
      display: block;
      margin-bottom: 6px;
      color: var(--amsol-orange);
      font-size: 10px;
      font-weight: 850;
      letter-spacing: 0.13em;
      text-transform: uppercase;
    }

    .amsol__visual-label strong {
      display: block;
      max-width: 360px;
      color: #fff;
      font-size: 22px;
      font-weight: 650;
      line-height: 1.2;
    }

    .amsol__visual-code {
      flex: 0 0 auto;
      color: #8f949d;
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
      font-size: 11px;
    }

    .amsol__float-node {
      position: absolute;
      z-index: 3;
      display: flex;
      width: 180px;
      align-items: center;
      gap: 12px;
      padding: 13px 15px;
      border: 1px solid rgba(255, 255, 255, 0.17);
      border-radius: 16px;
      color: #fff;
      background: rgba(25, 28, 34, 0.9);
      box-shadow: 0 18px 42px rgba(0, 0, 0, 0.24);
      backdrop-filter: blur(14px);
    }

    .amsol__float-node--one {
      top: 13px;
      left: -20px;
    }

    .amsol__float-node--two {
      top: 44%;
      right: -26px;
    }

    .amsol__float-node--three {
      bottom: 0;
      left: 45px;
    }

    .amsol__float-node i {
      display: grid;
      width: 34px;
      height: 34px;
      flex: 0 0 auto;
      place-items: center;
      border-radius: 10px;
      color: var(--amsol-orange);
      background: rgba(255, 115, 0, 0.12);
      font-size: 11px;
      font-style: normal;
      font-weight: 850;
    }

    .amsol__float-node span {
      color: #aeb3bc;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .amsol__float-node strong {
      display: block;
      margin-top: 2px;
      font-size: 13px;
      font-weight: 720;
    }

    /* Positioning strip */
    .amsol__strip {
      position: relative;
      z-index: 4;
      margin-top: -1px;
      border-bottom: 1px solid var(--amsol-line);
      background: #fff;
    }

    .amsol__strip-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
    }

    .amsol__strip-item {
      display: flex;
      min-height: 112px;
      align-items: center;
      gap: 16px;
      padding: 25px 30px;
      border-right: 1px solid var(--amsol-line);
    }

    .amsol__strip-item:first-child {
      border-left: 1px solid var(--amsol-line);
    }

    .amsol__strip-index {
      display: grid;
      width: 38px;
      height: 38px;
      flex: 0 0 auto;
      place-items: center;
      border-radius: 12px;
      color: var(--amsol-orange);
      background: var(--amsol-orange-soft);
      font-size: 11px;
      font-weight: 850;
    }

    .amsol__strip-item strong {
      display: block;
      margin-bottom: 3px;
      font-size: 15px;
      font-weight: 800;
    }

    .amsol__strip-item span {
      color: var(--amsol-muted);
      font-size: 12px;
    }

    /* Outcomes */
    .amsol__outcomes {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 18px;
    }

    .amsol__outcome {
      position: relative;
      min-height: 315px;
      overflow: hidden;
      padding: 30px;
      border: 1px solid var(--amsol-line);
      border-radius: var(--amsol-radius-lg);
      background: #fff;
      transition:
        transform 0.3s ease,
        box-shadow 0.3s ease,
        border-color 0.3s ease;
    }

    .amsol__outcome:hover {
      transform: translateY(-5px);
      border-color: #d8dadf;
      box-shadow: 0 22px 54px rgba(21, 23, 28, 0.08);
    }

    .amsol__outcome::after {
      position: absolute;
      right: -54px;
      bottom: -54px;
      width: 160px;
      height: 160px;
      border: 1px solid #eceef0;
      border-radius: 50%;
      box-shadow:
        0 0 0 24px rgba(245, 245, 243, 0.7),
        0 0 0 48px rgba(245, 245, 243, 0.45);
      content: "";
    }

    .amsol__outcome-icon {
      display: grid;
      width: 54px;
      height: 54px;
      place-items: center;
      margin-bottom: 54px;
      border-radius: 16px;
      color: var(--amsol-orange);
      background: var(--amsol-orange-soft);
    }

    .amsol__outcome-icon svg {
      width: 25px;
      height: 25px;
      fill: none;
      stroke: currentColor;
      stroke-linecap: round;
      stroke-linejoin: round;
      stroke-width: 1.7;
    }

    .amsol__outcome h3 {
      position: relative;
      z-index: 1;
      margin: 0 0 11px;
      color: var(--amsol-ink);
      font-size: 24px;
      font-weight: 700;
      letter-spacing: -0.035em;
      line-height: 1.15;
    }

    .amsol__outcome p {
      position: relative;
      z-index: 1;
      margin: 0;
      color: var(--amsol-muted);
      font-size: 14px;
      line-height: 1.65;
    }

    /* Digital route */
    .amsol__route-shell {
      position: relative;
      overflow: hidden;
      padding: 42px;
      border: 1px solid var(--amsol-line);
      border-radius: var(--amsol-radius-xl);
      background: #fff;
      box-shadow: var(--amsol-shadow);
    }

    .amsol__route-shell::before {
      position: absolute;
      top: -150px;
      right: -120px;
      width: 390px;
      height: 390px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255, 115, 0, 0.11), transparent 67%);
      content: "";
    }

    .amsol__route-top {
      position: relative;
      z-index: 1;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 40px;
    }

    .amsol__route-top span {
      color: var(--amsol-muted);
      font-size: 12px;
      font-weight: 750;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .amsol__route-status {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 11px;
      border: 1px solid #dfe2e6;
      border-radius: 999px;
      color: var(--amsol-ink) !important;
      background: #fafafa;
      letter-spacing: 0 !important;
      text-transform: none !important;
    }

    .amsol__route-status::before {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #23a86b;
      box-shadow: 0 0 0 4px rgba(35, 168, 107, 0.1);
      content: "";
    }

    .amsol__route {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 12px;
    }

    .amsol__route::before {
      position: absolute;
      z-index: -1;
      top: 34px;
      right: 7%;
      left: 7%;
      height: 2px;
      background: linear-gradient(90deg, var(--amsol-orange), #d7d9dd);
      content: "";
    }

    .amsol__route-step {
      text-align: center;
    }

    .amsol__route-icon {
      display: grid;
      width: 68px;
      height: 68px;
      place-items: center;
      margin: 0 auto 17px;
      border: 8px solid #fff;
      border-radius: 50%;
      color: var(--amsol-orange);
      background: var(--amsol-orange-soft);
      box-shadow: 0 0 0 1px #e6e8eb;
    }

    .amsol__route-icon svg {
      width: 24px;
      height: 24px;
      fill: none;
      stroke: currentColor;
      stroke-linecap: round;
      stroke-linejoin: round;
      stroke-width: 1.7;
    }

    .amsol__route-step strong {
      display: block;
      margin-bottom: 6px;
      font-size: 13px;
      font-weight: 820;
    }

    .amsol__route-step span {
      display: block;
      color: var(--amsol-muted);
      font-size: 11px;
      line-height: 1.45;
    }

    /* Solution cards */
    .amsol__solutions {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 20px;
    }

    .amsol__solution {
      position: relative;
      display: flex;
      min-height: 430px;
      flex-direction: column;
      overflow: hidden;
      padding: 34px;
      border: 1px solid var(--amsol-line);
      border-radius: var(--amsol-radius-lg);
      background: #fff;
      transition:
        transform 0.3s ease,
        box-shadow 0.3s ease;
    }

    .amsol__solution:hover {
      transform: translateY(-5px);
      box-shadow: 0 24px 64px rgba(21, 23, 28, 0.09);
    }

    .amsol__solution--dark {
      color: #fff;
      border-color: #2c3037;
      background:
        radial-gradient(circle at 100% 0, rgba(255, 115, 0, 0.18), transparent 38%),
        #1b1e23;
    }

    .amsol__solution-top {
      position: relative;
      z-index: 2;
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 20px;
      margin-bottom: 54px;
    }

    .amsol__solution-num {
      color: #afb3bb;
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.08em;
    }

    .amsol__solution-icon {
      display: grid;
      width: 48px;
      height: 48px;
      place-items: center;
      border-radius: 14px;
      color: var(--amsol-orange);
      background: var(--amsol-orange-soft);
    }

    .amsol__solution--dark .amsol__solution-icon {
      background: rgba(255, 115, 0, 0.13);
    }

    .amsol__solution-icon svg {
      width: 23px;
      height: 23px;
      fill: none;
      stroke: currentColor;
      stroke-linecap: round;
      stroke-linejoin: round;
      stroke-width: 1.7;
    }

    .amsol__solution h3 {
      position: relative;
      z-index: 2;
      max-width: 500px;
      margin: 0 0 14px;
      color: inherit;
      font-size: clamp(28px, 2.5vw, 38px);
      font-weight: 660;
      letter-spacing: -0.04em;
      line-height: 1.08;
    }

    .amsol__solution p {
      position: relative;
      z-index: 2;
      max-width: 520px;
      margin: 0 0 24px;
      color: var(--amsol-muted);
      font-size: 15px;
      line-height: 1.65;
    }

    .amsol__solution--dark p {
      color: #acb0b9;
    }

    .amsol__tags {
      position: relative;
      z-index: 2;
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 28px;
    }

    .amsol__tag {
      padding: 7px 10px;
      border: 1px solid #dde0e4;
      border-radius: 999px;
      color: #4e535c;
      background: #fafafa;
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.07em;
      text-transform: uppercase;
    }

    .amsol__solution--dark .amsol__tag {
      border-color: rgba(255, 255, 255, 0.13);
      color: #c6c9cf;
      background: rgba(255, 255, 255, 0.05);
    }

    .amsol__solution .amsol__text-link {
      position: relative;
      z-index: 2;
      margin-top: auto;
    }

    .amsol__solution-graphic {
      position: absolute;
      right: -55px;
      bottom: -82px;
      width: 270px;
      height: 270px;
      border: 1px solid #eaebed;
      border-radius: 50%;
      box-shadow:
        0 0 0 28px rgba(245, 245, 243, 0.66),
        0 0 0 57px rgba(245, 245, 243, 0.42);
    }

    .amsol__solution--dark .amsol__solution-graphic {
      border-color: rgba(255, 255, 255, 0.07);
      box-shadow:
        0 0 0 28px rgba(255, 255, 255, 0.025),
        0 0 0 57px rgba(255, 255, 255, 0.018);
    }

    /* Choice matrix */
    .amsol__matrix {
      overflow: hidden;
      border: 1px solid var(--amsol-line);
      border-radius: var(--amsol-radius-lg);
      background: #fff;
    }

    .amsol__matrix-row {
      display: grid;
      grid-template-columns: 0.78fr 1fr 1.15fr;
      border-top: 1px solid var(--amsol-line);
    }

    .amsol__matrix-row:first-child {
      border-top: 0;
    }

    .amsol__matrix-row > div {
      min-width: 0;
      padding: 22px 25px;
      border-left: 1px solid var(--amsol-line);
    }

    .amsol__matrix-row > div:first-child {
      border-left: 0;
    }

    .amsol__matrix-head {
      color: #8a8f98;
      background: #f8f8f7;
      font-size: 10px;
      font-weight: 850;
      letter-spacing: 0.11em;
      text-transform: uppercase;
    }

    .amsol__matrix-tech {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .amsol__matrix-tech i {
      display: grid;
      width: 35px;
      height: 35px;
      flex: 0 0 auto;
      place-items: center;
      border-radius: 11px;
      color: var(--amsol-orange);
      background: var(--amsol-orange-soft);
      font-size: 10px;
      font-style: normal;
      font-weight: 850;
    }

    .amsol__matrix-tech strong {
      font-size: 15px;
      font-weight: 820;
    }

    .amsol__matrix-row p {
      margin: 0;
      color: var(--amsol-muted);
      font-size: 13px;
      line-height: 1.55;
    }

    .amsol__matrix-row b {
      display: block;
      margin-bottom: 4px;
      color: var(--amsol-ink);
      font-size: 13px;
      font-weight: 780;
    }

    /* Implementation */
    .amsol__implementation {
      display: grid;
      grid-template-columns: minmax(300px, 0.72fr) minmax(0, 1.28fr);
      gap: 70px;
      align-items: start;
    }

    .amsol__implementation-intro {
      position: sticky;
      top: 30px;
    }

    .amsol__implementation-intro h2 {
      margin: 0 0 22px;
      font-size: clamp(38px, 4vw, 62px);
      font-weight: 650;
      letter-spacing: -0.045em;
      line-height: 1.03;
    }

    .amsol__implementation-intro p {
      margin: 0 0 30px;
      color: var(--amsol-muted);
      font-size: 16px;
      line-height: 1.7;
    }

    .amsol__steps {
      border-top: 1px solid var(--amsol-line);
    }

    .amsol__step {
      display: grid;
      grid-template-columns: 54px minmax(0, 1fr);
      gap: 20px;
      padding: 27px 0;
      border-bottom: 1px solid var(--amsol-line);
    }

    .amsol__step-num {
      display: grid;
      width: 48px;
      height: 48px;
      place-items: center;
      border-radius: 14px;
      color: var(--amsol-orange);
      background: var(--amsol-orange-soft);
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
      font-size: 11px;
      font-weight: 850;
    }

    .amsol__step-head {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 20px;
      margin-bottom: 8px;
    }

    .amsol__step h3 {
      margin: 0;
      color: var(--amsol-ink);
      font-size: 20px;
      font-weight: 750;
      letter-spacing: -0.025em;
    }

    .amsol__step-result {
      flex: 0 0 auto;
      color: #969ba4;
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .amsol__step p {
      margin: 0;
      color: var(--amsol-muted);
      font-size: 14px;
      line-height: 1.65;
    }

    /* Industries */
    .amsol__industries {
      display: grid;
      grid-template-columns: minmax(0, 1.08fr) minmax(350px, 0.92fr);
      gap: 24px;
    }

    .amsol__industry-visual {
      position: relative;
      min-height: 545px;
      overflow: hidden;
      border-radius: var(--amsol-radius-xl);
      background: #1b1e23;
    }

    .amsol__industry-visual::after {
      position: absolute;
      inset: 0;
      background:
        linear-gradient(to top, rgba(14, 16, 19, 0.93), transparent 62%),
        linear-gradient(90deg, rgba(14, 16, 19, 0.36), transparent 50%);
      content: "";
    }

    .amsol__industry-visual img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .amsol__industry-caption {
      position: absolute;
      z-index: 2;
      right: 34px;
      bottom: 31px;
      left: 34px;
    }

    .amsol__industry-caption span {
      color: var(--amsol-orange);
      font-size: 10px;
      font-weight: 850;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .amsol__industry-caption h3 {
      max-width: 560px;
      margin: 11px 0 0;
      color: #fff;
      font-size: clamp(28px, 3vw, 44px);
      font-weight: 640;
      letter-spacing: -0.04em;
      line-height: 1.08;
    }

    .amsol__industry-list {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
    }

    .amsol__industry {
      display: flex;
      min-height: 126px;
      flex-direction: column;
      justify-content: space-between;
      padding: 20px;
      border: 1px solid var(--amsol-line);
      border-radius: 17px;
      background: #fff;
      transition:
        transform 0.25s ease,
        border-color 0.25s ease;
    }

    .amsol__industry:hover {
      transform: translateY(-3px);
      border-color: #cfd2d6;
    }

    .amsol__industry span {
      color: #a0a4ac;
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
      font-size: 10px;
    }

    .amsol__industry strong {
      font-size: 14px;
      font-weight: 760;
      line-height: 1.3;
    }

    /* Engineering */
    .amsol__engineering {
      display: grid;
      grid-template-columns: minmax(0, 0.83fr) minmax(430px, 1.17fr);
      gap: 24px;
      align-items: stretch;
    }

    .amsol__engineering-copy {
      display: flex;
      min-height: 510px;
      flex-direction: column;
      justify-content: space-between;
      padding: 43px;
      border-radius: var(--amsol-radius-xl);
      color: #fff;
      background:
        radial-gradient(circle at 100% 0, rgba(255, 115, 0, 0.19), transparent 40%),
        #17191d;
    }

    .amsol__engineering-copy h2 {
      max-width: 540px;
      margin: 0 0 22px;
      color: #fff;
      font-size: clamp(38px, 4vw, 60px);
      font-weight: 640;
      letter-spacing: -0.045em;
      line-height: 1.03;
    }

    .amsol__engineering-copy p {
      max-width: 530px;
      margin: 0;
      color: #afb3bc;
      font-size: 15px;
      line-height: 1.7;
    }

    .amsol__engineering-facts {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
      margin-top: 34px;
    }

    .amsol__engineering-fact {
      padding: 17px;
      border: 1px solid rgba(255, 255, 255, 0.13);
      border-radius: 15px;
      background: rgba(255, 255, 255, 0.045);
    }

    .amsol__engineering-fact strong {
      display: block;
      margin-bottom: 4px;
      color: #fff;
      font-size: 19px;
      font-weight: 760;
    }

    .amsol__engineering-fact span {
      color: #999ea8;
      font-size: 11px;
      line-height: 1.45;
    }

    .amsol__engineering-panel {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 14px;
      padding: 18px;
      border: 1px solid var(--amsol-line);
      border-radius: var(--amsol-radius-xl);
      background: #fff;
    }

    .amsol__engineering-card {
      display: flex;
      min-height: 224px;
      flex-direction: column;
      justify-content: space-between;
      padding: 24px;
      border-radius: 19px;
      background: var(--amsol-bg);
    }

    .amsol__engineering-card:nth-child(2) {
      background: var(--amsol-orange-soft);
    }

    .amsol__engineering-card:nth-child(3) {
      background: #23262c;
    }

    .amsol__engineering-card:nth-child(4) {
      border: 1px solid var(--amsol-line);
      background: #fff;
    }

    .amsol__engineering-card i {
      display: grid;
      width: 42px;
      height: 42px;
      place-items: center;
      border-radius: 13px;
      color: var(--amsol-orange);
      background: #fff;
      box-shadow: 0 8px 22px rgba(20, 22, 27, 0.07);
      font-size: 11px;
      font-style: normal;
      font-weight: 850;
    }

    .amsol__engineering-card:nth-child(3) i {
      background: rgba(255, 255, 255, 0.08);
    }

    .amsol__engineering-card span {
      display: block;
      margin-bottom: 7px;
      color: #8d929b;
      font-size: 10px;
      font-weight: 850;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .amsol__engineering-card strong {
      display: block;
      color: var(--amsol-ink);
      font-size: 18px;
      font-weight: 760;
      line-height: 1.25;
    }

    .amsol__engineering-card:nth-child(3) strong {
      color: #fff;
    }

    /* FAQ */
    .amsol__faq {
      display: grid;
      grid-template-columns: minmax(280px, 0.65fr) minmax(0, 1.35fr);
      gap: 80px;
      align-items: start;
    }

    .amsol__faq-intro h2 {
      margin: 0 0 18px;
      font-size: clamp(38px, 4vw, 60px);
      font-weight: 650;
      letter-spacing: -0.045em;
      line-height: 1.03;
    }

    .amsol__faq-intro p {
      margin: 0;
      color: var(--amsol-muted);
      line-height: 1.7;
    }

    .amsol__faq-list {
      border-top: 1px solid var(--amsol-line);
    }

    .amsol details {
      border-bottom: 1px solid var(--amsol-line);
    }

    .amsol details summary {
      position: relative;
      padding: 25px 55px 25px 0;
      cursor: pointer;
      color: var(--amsol-ink);
      font-size: 17px;
      font-weight: 750;
      list-style: none;
    }

    .amsol details summary::-webkit-details-marker {
      display: none;
    }

    .amsol details summary::before,
    .amsol details summary::after {
      position: absolute;
      top: 50%;
      right: 8px;
      width: 17px;
      height: 2px;
      background: var(--amsol-orange);
      transform: translateY(-50%);
      transition: transform 0.25s ease;
      content: "";
    }

    .amsol details summary::after {
      transform: translateY(-50%) rotate(90deg);
    }

    .amsol details[open] summary::after {
      transform: translateY(-50%) rotate(0);
    }

    .amsol details p {
      max-width: 760px;
      margin: -5px 0 26px;
      color: var(--amsol-muted);
      font-size: 14px;
      line-height: 1.7;
    }

    /* CTA */
    .amsol__cta {
      position: relative;
      overflow: hidden;
      padding: 84px 0;
      color: #fff;
      background:
        radial-gradient(circle at 83% 35%, rgba(255, 115, 0, 0.22), transparent 29%),
        #111317;
    }

    .amsol__cta::before {
      position: absolute;
      right: -140px;
      bottom: -280px;
      width: 620px;
      height: 620px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 50%;
      box-shadow:
        0 0 0 60px rgba(255, 255, 255, 0.018),
        0 0 0 120px rgba(255, 255, 255, 0.012);
      content: "";
    }

    .amsol__cta-grid {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 60px;
      align-items: center;
    }

    .amsol__cta h2 {
      max-width: 830px;
      margin: 0 0 19px;
      color: #fff;
      font-size: clamp(40px, 5vw, 70px);
      font-weight: 630;
      letter-spacing: -0.05em;
      line-height: 1.02;
    }

    .amsol__cta p {
      max-width: 680px;
      margin: 0;
      color: #aeb3bc;
      font-size: 16px;
      line-height: 1.7;
    }

    .amsol__cta-actions {
      display: flex;
      min-width: 225px;
      flex-direction: column;
      gap: 11px;
    }

    .amsol__cta-note {
      color: #8e939d;
      font-size: 11px;
      line-height: 1.5;
      text-align: center;
    }

    /* Bitrix24 modal */
    .amsol__modal {
      position: fixed;
      z-index: 999999;
      inset: 0;
      display: flex;
      padding: 24px;
      align-items: center;
      justify-content: center;
      visibility: hidden;
      opacity: 0;
      background: rgba(10, 12, 15, 0.76);
      backdrop-filter: blur(10px);
      transition:
        opacity 0.25s ease,
        visibility 0.25s ease;
    }

    .amsol__modal.is-open {
      visibility: visible;
      opacity: 1;
    }

    .amsol__modal-dialog {
      position: relative;
      width: min(720px, 100%);
      max-height: calc(100vh - 48px);
      overflow: auto;
      padding: 32px;
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 26px;
      background: #fff;
      box-shadow: 0 34px 100px rgba(0, 0, 0, 0.34);
      transform: translateY(18px) scale(0.985);
      transition: transform 0.25s ease;
    }

    .amsol__modal.is-open .amsol__modal-dialog {
      transform: translateY(0) scale(1);
    }

    .amsol__modal-head {
      padding: 0 52px 22px 0;
    }

    .amsol__modal-head h2 {
      margin: 0 0 9px;
      color: var(--amsol-ink);
      font-size: clamp(27px, 4vw, 38px);
      font-weight: 680;
      letter-spacing: -0.04em;
      line-height: 1.1;
    }

    .amsol__modal-head p {
      margin: 0;
      color: var(--amsol-muted);
      font-size: 14px;
      line-height: 1.6;
    }

    .amsol__modal-close {
      position: absolute;
      z-index: 2;
      top: 22px;
      right: 22px;
      display: grid;
      width: 42px;
      height: 42px;
      place-items: center;
      border: 1px solid var(--amsol-line);
      border-radius: 50%;
      color: var(--amsol-ink);
      background: #fff;
      cursor: pointer;
      font-size: 26px;
      line-height: 1;
      transition:
        transform 0.2s ease,
        background-color 0.2s ease;
    }

    .amsol__modal-close:hover {
      transform: rotate(5deg);
      background: var(--amsol-bg);
    }

    body.amsol-modal-lock {
      overflow: hidden;
    }

    /* Responsive */
    @media (max-width: 1120px) {
      .amsol__hero-grid {
        grid-template-columns: minmax(0, 0.94fr) minmax(400px, 1.06fr);
        gap: 38px;
      }

      .amsol__float-node--one {
        left: 5px;
      }

      .amsol__float-node--two {
        right: 5px;
      }

      .amsol__route-shell {
        padding: 34px 26px;
      }

      .amsol__route {
        gap: 5px;
      }

      .amsol__engineering {
        grid-template-columns: 1fr;
      }

      .amsol__engineering-copy {
        min-height: auto;
      }
    }

    @media (max-width: 920px) {
      .amsol {
        --amsol-header-clearance: 78px;
      }

      .amsol__section {
        padding: 84px 0;
      }

      .amsol__section-head {
        grid-template-columns: 1fr;
        gap: 20px;
      }

      .amsol__section-head p {
        max-width: 680px;
      }

      .amsol__hero-grid {
        grid-template-columns: 1fr;
        padding-top: calc(65px + var(--amsol-header-clearance));
      }

      .amsol__hero-copy {
        max-width: 760px;
      }

      .amsol__hero-visual {
        min-height: 560px;
      }

      .amsol__visual-card {
        inset: 35px 0 30px;
      }

      .amsol__strip-item {
        padding: 22px 18px;
      }

      .amsol__outcomes {
        grid-template-columns: 1fr;
      }

      .amsol__outcome {
        min-height: auto;
      }

      .amsol__outcome-icon {
        margin-bottom: 34px;
      }

      .amsol__route {
        grid-template-columns: repeat(3, 1fr);
        gap: 30px 12px;
      }

      .amsol__route::before {
        display: none;
      }

      .amsol__solutions {
        grid-template-columns: 1fr;
      }

      .amsol__implementation {
        grid-template-columns: 1fr;
        gap: 46px;
      }

      .amsol__implementation-intro {
        position: static;
      }

      .amsol__industries {
        grid-template-columns: 1fr;
      }

      .amsol__industry-visual {
        min-height: 490px;
      }

      .amsol__faq {
        grid-template-columns: 1fr;
        gap: 42px;
      }

      .amsol__cta-grid {
        grid-template-columns: 1fr;
        gap: 35px;
      }

      .amsol__cta-actions {
        width: min(320px, 100%);
      }
    }

    @media (max-width: 700px) {
      .amsol {
        --amsol-header-clearance: 68px;
      }

      .amsol__container {
        width: min(100% - 32px, 1240px);
      }

      .amsol__section {
        padding: 68px 0;
      }

      .amsol__section-head {
        margin-bottom: 34px;
      }

      .amsol__section-head h2 {
        font-size: clamp(30px, 8.8vw, 42px);
        line-height: 1.06;
      }

      .amsol__hero {
        min-height: 0;
      }

      .amsol__hero-grid {
        min-height: 0;
        gap: 36px;
        padding: calc(38px + var(--amsol-header-clearance)) 0 42px;
      }

      .amsol__hero h1 {
        font-size: clamp(36px, 10.5vw, 50px);
        letter-spacing: -0.045em;
        line-height: 1.02;
      }

      .amsol__hero-lead {
        margin-top: 23px;
        font-size: 16px;
      }

      .amsol__hero-actions {
        display: grid;
        grid-template-columns: 1fr;
      }

      .amsol__hero-actions .amsol__button {
        width: 100%;
      }

      .amsol__hero-facts {
        grid-template-columns: 1fr;
      }

      .amsol__hero-fact {
        min-height: auto;
      }

      .amsol__hero-visual {
        min-height: 410px;
      }

      .amsol__visual-card {
        inset: 30px 0 36px;
        border-radius: 22px;
      }

      .amsol__visual-label {
        right: 18px;
        bottom: 18px;
        left: 18px;
      }

      .amsol__visual-label strong {
        font-size: 17px;
      }

      .amsol__visual-code {
        display: none;
      }

      .amsol__float-node {
        width: auto;
        max-width: 180px;
        padding: 10px 12px;
      }

      .amsol__float-node--one {
        top: 0;
      }

      .amsol__float-node--two {
        top: 45%;
      }

      .amsol__float-node--three {
        bottom: 0;
        left: 18px;
      }

      .amsol__strip-grid {
        grid-template-columns: 1fr;
      }

      .amsol__strip-item,
      .amsol__strip-item:first-child {
        min-height: auto;
        border-right: 1px solid var(--amsol-line);
        border-bottom: 1px solid var(--amsol-line);
        border-left: 1px solid var(--amsol-line);
      }

      .amsol__strip-item:last-child {
        border-bottom: 0;
      }

      .amsol__route-shell {
        padding: 26px 18px;
        border-radius: 22px;
      }

      .amsol__route-top {
        align-items: flex-start;
        flex-direction: column;
        margin-bottom: 30px;
      }

      .amsol__route {
        grid-template-columns: repeat(2, 1fr);
        gap: 28px 10px;
      }

      .amsol__solution {
        min-height: 390px;
        padding: 27px 24px;
      }

      .amsol__solution h3 {
        font-size: clamp(25px, 7.8vw, 34px);
        line-height: 1.08;
      }

      .amsol__solution-top {
        margin-bottom: 42px;
      }

      .amsol__matrix {
        border: 0;
        border-radius: 0;
        background: transparent;
      }

      .amsol__matrix-row,
      .amsol__matrix-row:first-child {
        display: block;
        margin-bottom: 12px;
        overflow: hidden;
        border: 1px solid var(--amsol-line);
        border-radius: 17px;
        background: #fff;
      }

      .amsol__matrix-row > div {
        padding: 17px 19px;
        border-top: 1px solid var(--amsol-line);
        border-left: 0;
      }

      .amsol__matrix-row > div:first-child {
        border-top: 0;
      }

      .amsol__matrix-head {
        display: none;
      }

      .amsol__step {
        grid-template-columns: 45px minmax(0, 1fr);
        gap: 14px;
      }

      .amsol__step-num {
        width: 43px;
        height: 43px;
      }

      .amsol__step-head {
        align-items: flex-start;
        flex-direction: column;
        gap: 5px;
      }

      .amsol__industry-visual {
        min-height: 390px;
        border-radius: 22px;
      }

      .amsol__industry-caption {
        right: 23px;
        bottom: 23px;
        left: 23px;
      }

      .amsol__industry-list {
        grid-template-columns: 1fr;
      }

      .amsol__engineering-copy {
        min-height: auto;
        padding: 29px 24px;
        border-radius: 22px;
      }

      .amsol__engineering-panel {
        grid-template-columns: 1fr;
        padding: 12px;
        border-radius: 22px;
      }

      .amsol__engineering-card {
        min-height: 180px;
      }

      .amsol__faq-intro h2 {
        font-size: clamp(30px, 8.8vw, 40px);
        line-height: 1.06;
      }

      .amsol details summary {
        font-size: 15px;
      }

      .amsol__cta {
        padding: 67px 0;
      }

      .amsol__cta h2 {
        font-size: clamp(31px, 9vw, 42px);
        line-height: 1.06;
      }

      .amsol__cta-actions {
        width: 100%;
      }

      .amsol__modal {
        padding: 12px;
        align-items: flex-start;
