  <script>
    (function () {
      var root = document.getElementById("amtech-industrial-solutions");
      if (!root) return;

      var modal = root.querySelector("#amsol-form-modal");
      var dialog = root.querySelector(".amsol__modal-dialog");
      var closeButton = root.querySelector(".amsol__modal-close");
      var triggers = root.querySelectorAll("[data-amsol-open-form]");
      var lastFocused = null;

      function openModal() {
        lastFocused = document.activeElement;
        modal.classList.add("is-open");
        modal.setAttribute("aria-hidden", "false");
        document.body.classList.add("amsol-modal-lock");
        window.setTimeout(function () {
          closeButton.focus();
        }, 30);
      }

      function closeModal() {
        modal.classList.remove("is-open");
        modal.setAttribute("aria-hidden", "true");
        document.body.classList.remove("amsol-modal-lock");
        if (lastFocused && typeof lastFocused.focus === "function") {
          lastFocused.focus();
        }
      }

      for (var i = 0; i < triggers.length; i += 1) {
        triggers[i].addEventListener("click", openModal);
      }

      closeButton.addEventListener("click", closeModal);

      modal.addEventListener("click", function (event) {
        if (event.target === modal) closeModal();
      });

      dialog.addEventListener("click", function (event) {
        event.stopPropagation();
      });

      document.addEventListener("keydown", function (event) {
        if (event.key === "Escape" && modal.classList.contains("is-open")) {
          closeModal();
        }
      });
    })();
  </script>

